1	package com.example.starter.observation;
2	
3	import org.junit.jupiter.api.BeforeEach;
4	import org.junit.jupiter.api.Test;
5	import org.springframework.beans.factory.annotation.Autowired;
6	import org.springframework.boot.test.context.SpringBootTest;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	
9	import java.util.ArrayList;
10	import java.util.List;
11	import java.util.Map;
12	import java.util.concurrent.Callable;
13	import java.util.concurrent.CountDownLatch;
14	import java.util.concurrent.ExecutorService;
15	import java.util.concurrent.Executors;
16	import java.util.concurrent.Future;
17	import java.util.concurrent.TimeUnit;
18	
19	import static org.assertj.core.api.Assertions.assertThat;
20	
21	/**
22	 * 冲突解决并发边界测试：真实并发提交，验证只有匹配实际当前版本者成功、
23	 * 解决与删除竞争不覆盖新版本或复活墓碑、同 resolutionId 并发重放只生成一条记录。
24	 */
25	@SpringBootTest
26	class ResolutionConcurrencyTest {
27	
28	    @Autowired
29	    private ObservationService observationService;
30	
31	    @Autowired
32	    private JdbcTemplate jdbcTemplate;
33	
34	    @BeforeEach
35	    void cleanDatabase() {
36	        jdbcTemplate.update("DELETE FROM conflict_resolution");
37	        jdbcTemplate.update("DELETE FROM request_log");
38	        jdbcTemplate.update("DELETE FROM observation_version");
39	        jdbcTemplate.update("DELETE FROM observation_current");
40	    }
41	
42	    private <T> List<T> runConcurrently(List<Callable<T>> tasks) throws Exception {
43	        ExecutorService executor = Executors.newFixedThreadPool(tasks.size());
44	        CountDownLatch ready = new CountDownLatch(tasks.size());
45	        CountDownLatch start = new CountDownLatch(1);
46	        List<Callable<T>> synchronizedTasks = tasks.stream()
47	                .<Callable<T>>map(task -> () -> {
48	                    ready.countDown();
49	                    start.await(10, TimeUnit.SECONDS);
50	                    return task.call();
51	                })
52	                .toList();
53	        try {
54	            List<Future<T>> futures = synchronizedTasks.stream().map(executor::submit).toList();
55	            if (!ready.await(10, TimeUnit.SECONDS)) {
56	                throw new IllegalStateException("workers not ready in time");
57	            }
58	            start.countDown();
59	            List<T> results = new ArrayList<>();
60	            for (Future<T> future : futures) {
61	                results.add(future.get(30, TimeUnit.SECONDS));
62	            }
63	            return results;
64	        } finally {
65	            executor.shutdownNow();
66	        }
67	    }
68	
69	    private void setupLocationConflict(String observationId, String tag) {
70	        observationService.create(new CreateObservationRequest(
71	                "req-" + tag + "-0", observationId, "站点A", "1.0", "备注"));
72	        observationService.merge(observationId, new MergeObservationRequest(
73	                "req-" + tag + "-1", 1, "站点B", "1.0", "备注"));
74	        // 离线端基于 v1 改站点C：与服务端站点B 冲突，普通合并失败不占键
75	        try {
76	            observationService.merge(observationId, new MergeObservationRequest(
77	                    "req-" + tag + "-2", 1, "站点C", "1.0", "备注"));
78	            throw new IllegalStateException("expected merge conflict");
79	        } catch (ApiException e) {
80	            assertThat(e.status().value()).isEqualTo(409);
81	        }
82	    }
83	
84	    private ResolveConflictRequest resolveRequest(String requestId, String resolutionId,
85	                                                  int expectedCurrentVersion) {
86	        return new ResolveConflictRequest(requestId, resolutionId, 1, expectedCurrentVersion,
87	                "站点C", "1.0", "备注", Map.of("location", "CANDIDATE"), "operator-a");
88	    }
89	
90	    @Test
91	    void concurrentResolvesOnlyVersionMatcherSucceeds() throws Exception {
92	        setupLocationConflict("obs-x1", "x1");
93	
94	        // 两个解决请求都期望当前为 v2：先提交者推进到 v3，后到者版本不匹配 409，不得覆盖新版本
95	        List<Callable<String>> tasks = List.of(
96	                () -> {
97	                    try {
98	                        ObservationService.ResolveOutcome outcome = observationService.resolveConflict(
99	                                "obs-x1", resolveRequest("req-x1-a", "res-x1-a", 2));
100	                        return "ok-" + outcome.body().version();
101	                    } catch (ApiException e) {
102	                        return String.valueOf(e.status().value());
103	                    }
104	                },
105	                () -> {
106	                    try {
107	                        ObservationService.ResolveOutcome outcome = observationService.resolveConflict(
108	                                "obs-x1", resolveRequest("req-x1-b", "res-x1-b", 2));
109	                        return "ok-" + outcome.body().version();
110	                    } catch (ApiException e) {
111	                        return String.valueOf(e.status().value());
112	                    }
113	                });
114	        List<String> results = runConcurrently(tasks);
115	
116	        assertThat(results).containsExactlyInAnyOrder("ok-3", "409");
117	        ObservationResponse current = observationService.getCurrent("obs-x1");
118	        assertThat(current.version()).isEqualTo(3);
119	        assertThat(current.location()).isEqualTo("站点C");
120	        Integer versionRows = jdbcTemplate.queryForObject(
121	                "SELECT COUNT(*) FROM observation_version WHERE observation_id = 'obs-x1'", Integer.class);
122	        assertThat(versionRows).isEqualTo(3);
123	        Integer resolutionRows = jdbcTemplate.queryForObject(
124	                "SELECT COUNT(*) FROM conflict_resolution WHERE observation_id = 'obs-x1'", Integer.class);
125	        assertThat(resolutionRows).isEqualTo(1);
126	        // 两个不同 requestId 中只有成功方占位落库；失败事务回滚，不占 requestId
127	        Integer totalRequestRows = jdbcTemplate.queryForObject(
128	                "SELECT COUNT(*) FROM request_log WHERE request_id IN ('req-x1-a','req-x1-b')", Integer.class);
129	        assertThat(totalRequestRows).isEqualTo(1);
130	        // 落库的解决记录与成功请求一一对应
131	        String storedResolutionId = jdbcTemplate.queryForObject(
132	                "SELECT resolution_id FROM conflict_resolution WHERE observation_id = 'obs-x1'", String.class);
133	        String storedRequestId = jdbcTemplate.queryForObject(
134	                "SELECT request_id FROM conflict_resolution WHERE observation_id = 'obs-x1'", String.class);
135	        assertThat(storedResolutionId).startsWith("res-x1-");
136	        assertThat(storedRequestId).isEqualTo("req-" + storedResolutionId.substring("res-".length()));
137	    }
138	
139	    @Test
140	    void concurrentResolveAndDeleteNeverOverwritesOrResurrects() throws Exception {
141	        setupLocationConflict("obs-x2", "x2");
142	
143	        List<Callable<String>> tasks = List.of(
144	                () -> {
145	                    try {
146	                        observationService.resolveConflict(
147	                                "obs-x2", resolveRequest("req-x2-r", "res-x2", 2));
148	                        return "resolve-ok";
149	                    } catch (ApiException e) {
150	                        return "resolve-" + e.status().value();
151	                    }
152	                },
153	                () -> {
154	                    try {
155	                        observationService.delete("obs-x2", new DeleteObservationRequest("req-x2-d", 2));
156	                        return "delete-ok";
157	                    } catch (ApiException e) {
158	                        return "delete-" + e.status().value();
159	                    }
160	                });
161	        List<String> results = runConcurrently(tasks);
162	
163	        ObservationResponse current = observationService.getCurrent("obs-x2");
164	        if (results.contains("resolve-ok")) {
165	            // 解决先生效：内容为站点C/v3，删除因版本不匹配失败
166	            assertThat(results).containsExactlyInAnyOrder("resolve-ok", "delete-409");
167	            assertThat(current.deleted()).isFalse();
168	            assertThat(current.version()).isEqualTo(3);
169	            assertThat(current.location()).isEqualTo("站点C");
170	        } else {
171	            // 删除先生效：墓碑 v3 不得被并发解决复活，解决返回 410
172	            assertThat(results).containsExactlyInAnyOrder("delete-ok", "resolve-410");
173	            assertThat(current.deleted()).isTrue();
174	            assertThat(current.version()).isEqualTo(3);
175	        }
176	        Integer versionRows = jdbcTemplate.queryForObject(
177	                "SELECT COUNT(*) FROM observation_version WHERE observation_id = 'obs-x2'", Integer.class);
178	        assertThat(versionRows).isEqualTo(3);
179	    }
180	
181	    @Test
182	    void concurrentSameResolutionIdWithSameParamsReplaysSingleRecord() throws Exception {
183	        setupLocationConflict("obs-x3", "x3");
184	
185	        // 同一 resolutionId、相同参数、不同 requestId 并发 3 次：全部返回同一结果，只生成一个新版本与一张解决记录
186	        List<Callable<ObservationService.ResolveOutcome>> tasks = new ArrayList<>();
187	        tasks.add(() -> observationService.resolveConflict(
188	                "obs-x3", resolveRequest("req-x3-a", "res-x3", 2)));
189	        tasks.add(() -> observationService.resolveConflict(
190	                "obs-x3", resolveRequest("req-x3-b", "res-x3", 2)));
191	        tasks.add(() -> observationService.resolveConflict(
192	                "obs-x3", resolveRequest("req-x3-c", "res-x3", 2)));
193	        List<ObservationService.ResolveOutcome> outcomes = runConcurrently(tasks);
194	
195	        assertThat(outcomes).allMatch(outcome -> outcome.status() == 200);
196	        assertThat(outcomes).allMatch(outcome -> outcome.body().version() == 3);
197	        assertThat(outcomes).allMatch(outcome -> "res-x3".equals(outcome.body().resolutionId()));
198	        ObservationResponse current = observationService.getCurrent("obs-x3");
199	        assertThat(current.version()).isEqualTo(3);
200	        assertThat(current.location()).isEqualTo("站点C");
201	        Integer resolutionRows = jdbcTemplate.queryForObject(
202	                "SELECT COUNT(*) FROM conflict_resolution WHERE resolution_id = 'res-x3'", Integer.class);
203	        assertThat(resolutionRows).isEqualTo(1);
204	        Integer versionRows = jdbcTemplate.queryForObject(
205	                "SELECT COUNT(*) FROM observation_version WHERE observation_id = 'obs-x3'", Integer.class);
206	        assertThat(versionRows).isEqualTo(3);
207	        // 三个不同 requestId 各有一条成功重放记录
208	        Integer requestRows = jdbcTemplate.queryForObject(
209	                "SELECT COUNT(*) FROM request_log WHERE request_id IN ('req-x3-a','req-x3-b','req-x3-c')",
210	                Integer.class);
211	        assertThat(requestRows).isEqualTo(3);
212	    }
213	
214	    @Test
215	    void concurrentSameRequestIdResolvesReplaysSingleResult() throws Exception {
216	        setupLocationConflict("obs-x4", "x4");
217	
218	        // 同一 requestId + 同一 resolutionId + 相同参数并发 3 次：只占一键、只生成一个新版本
219	        List<Callable<ObservationService.ResolveOutcome>> tasks = new ArrayList<>();
220	        for (int i = 0; i < 3; i++) {
221	            tasks.add(() -> observationService.resolveConflict(
222	                    "obs-x4", resolveRequest("req-x4-same", "res-x4", 2)));
223	        }
224	        List<ObservationService.ResolveOutcome> outcomes = runConcurrently(tasks);
225	
226	        assertThat(outcomes).allMatch(outcome -> outcome.status() == 200);
227	        assertThat(outcomes).allMatch(outcome -> outcome.body().version() == 3);
228	        Integer requestRows = jdbcTemplate.queryForObject(
229	                "SELECT COUNT(*) FROM request_log WHERE request_id = 'req-x4-same'", Integer.class);
230	        assertThat(requestRows).isEqualTo(1);
231	        Integer resolutionRows = jdbcTemplate.queryForObject(
232	                "SELECT COUNT(*) FROM conflict_resolution WHERE resolution_id = 'res-x4'", Integer.class);
