    ReleaseSnapshotRecord release = releaseIfDue(embargo, now);
    return releasedView(ReleaseResponse.of(release, objectMapper));
}

private ReleaseSnapshotRecord releaseIfDue(EmbargoRecord embargo, Instant now) {
    Optional<ReleaseSnapshotRecord> existing = releaseRepository.findRelease(embargo.observationId());
    if (existing.isPresent()) return existing.get();
    // 行锁串行化：与更正（merge/resolve/delete）按提交顺序裁决
    ObservationSnapshot current = observationRepository.findCurrentForUpdate(embargo.observationId())
        .orElseThrow(notFound);
    List<ResolutionRecord> resolutions = resolutionRepository.findByObservationId(embargo.observationId());
    List<ResolutionSummary> summaries = ...;
    List<String> flags = qualityFlags(current, embargo, resolutions);
