        current.version(), current.location(), current.reading(), current.note(), current.deleted(),
        writeJson(summaries), writeJson(flags), now);
    try {
        releaseRepository.insertRelease(record);
        return record;
    } catch (DuplicateKeyException e) {
        return releaseRepository.findRelease(observationId).orElseThrow(...);
    }
}
