                    }
                });
        List<String> results = runConcurrently(tasks);

        assertThat(results.get(0)).isEqualTo("merged");
        assertThat(results.get(1)).matches("released-[12]");
        assertThat(countRows("embargo_release", "obs-x4")).isEqualTo(1);
